/**
 * Unit tests for BasicDeserializerFactory._addExplicitDelegatingCreator
 */
public class BasicDeserializerFactory__addExplicitDelegatingCreator_TriageGen1Test {

    private BasicDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private CreatorCollector creators;

    @Before
    public void setUp() {
        // BasicDeserializerFactory is protected/abstract-ish in usage, 
        // we use a mock or a subclass to test the protected method.
        factory = spy(new BasicDeserializerFactory(null) {
            @Override
            protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
                return this;
            }
        });
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        creators = mock(CreatorCollector.class);
    }

    /**
     * Helper to create a mock Candidate
     */
    private CreatorCandidate createMockCandidate(int paramCount, List<AnnotatedParameter> params, List<JacksonInject.Value> injects, AnnotatedWithParams creator) {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(paramCount);
        when(candidate.creator()).thenReturn(creator);

        for (int i = 0; i < paramCount; i++) {
            when(candidate.parameter(i)).thenReturn(params.get(i));
            when(candidate.injection(i)).thenReturn(injects.get(i));
        }
        return candidate;
    }

    @Test
    public void testAddExplicitDelegatingCreator_SingleArgument_Success() throws JsonMappingException {
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        POJOPropertyBuilder propBuilder = mock(POJOPropertyBuilder.class);
        BeanPropertyDefinition propDef = mock(BeanPropertyDefinition.class);

        when(propDef.getBuilder()).thenReturn(propBuilder);

        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(creator);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(propDef);

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        // Verify single argument logic: calls _handleSingleArgumentCreator and removes constructors
        verify(factory)._handleSingleArgumentCreator(creators, creator, true, true);
        verify(propBuilder).removeConstructors();
        verify(creators, never()).addDelegatingCreator(any(), anyBoolean(), any(), anyInt());
    }

    @Test
    public void testAddExplicitDelegatingCreator_MultipleArguments_Success() throws JsonMappingException {
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);
        AnnotatedParameter param1 = mock(AnnotatedParameter.class);

        // Param 0 is delegating (not injected), Param 1 is injected
        List<AnnotatedParameter> params = List.of(param0, param1);
        List<JacksonInject.Value> injects = List.of(null, mock(JacksonInject.Value.class));

        CreatorCandidate candidate = createMockCandidate(2, params, injects, creator);

        // Mock the construction of the property for the injected param
        SettableBeanProperty mockProp = mock(SettableBeanProperty.class);
        doReturn(mockProp).when(factory).constructCreatorProperty(eq(ctxt), eq(beanDesc), any(), eq(1), eq(param1), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        // Verify it calls addDelegatingCreator with the correct index (0) and properties array
        verify(creators).addDelegatingCreator(eq(creator), eq(true), any(SettableBeanProperty[].class), eq(0));
    }

    @Test(expected = JsonMappingException.class)
    public void testAddExplicitDelegatingCreator_TooManyDelegatingArguments_ThrowsException() throws JsonMappingException {
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);
        AnnotatedParameter param1 = mock(AnnotatedParameter.class);

        // Both params are non-injected -> both try to be the delegating argument
        List<AnnotatedParameter> params = List.of(param0, param1);
        List<JacksonInject.Value> injects = List.of(null, null);

        CreatorCandidate candidate = createMockCandidate(2, params, injects, creator);

        // Stub reportBadTypeDefinition to throw exception to simulate Jackson behavior
        doThrow(new JsonMappingException(null, "Error"))
                .when(ctxt).reportBadTypeDefinition(eq(beanDesc), anyString(), any(), any(), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
    }

    @Test(expected = JsonMappingException.class)
    public void testAddExplicitDelegatingCreator_NoDelegatingArgument_ThrowsException() throws JsonMappingException {
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);

        // Parameter is injected, so there is no "leftover" delegating argument
        List<AnnotatedParameter> params = List.of(param0);
        List<JacksonInject.Value> injects = List.of(mock(JacksonInject.Value.class));

        CreatorCandidate candidate = createMockCandidate(1, params, injects, creator);

        doThrow(new JsonMappingException(null, "Error"))
                .when(ctxt).reportBadTypeDefinition(eq(beanDesc), anyString(), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
    }

    @Test
    public void testAddExplicitDelegatingCreator_SingleArgument_NoPropertyDef_Success() throws JsonMappingException {
        // Test path where candidate.propertyDef(0) returns null
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);

        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(creator);
        when(candidate.parameter(0)).thenReturn(param0);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(null);

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        verify(factory)._handleSingleArgumentCreator(creators, creator, true, true);
        verify(creators, never()).addDelegatingCreator(any(), anyBoolean(), any(), anyInt());
    }
}
